-- Arizona. The state had fourteen stops, all from the original scan.
--
-- Four are the same places as entries in this file and three of them have
-- coordinates wrong by around a kilometre — Gold King Mine by 1,013 metres and
-- Vulture City by 978. So they are deleted and replaced rather than merged,
-- the same call made for Colorado, because the on-conflict clause leaves
-- coordinates alone by design and here the old ones are worse.
--
-- Vulture City is the interesting one: it is held as
-- vulture-mine-tours-vulture-city-ghost-town and arrives as Vulture City Ghost
-- Town, so the slug check saw nothing and the position check saw a kilometre.
-- Only reading the names found it. That is the third time a bad scan
-- coordinate has hidden a duplicate from both tests.
--
-- The only state where the clocks disagree with themselves. The Navajo Nation
-- observes daylight saving and the rest of Arizona does not, so 15 stops are
-- America/Denver and the remaining 185 are America/Phoenix.
--
-- Listed by town, because the boundary is a reservation border rather than a
-- line of longitude. Winslow and the Petrified Forest sit in Navajo and Apache
-- counties but off-reservation, and a coordinate rule gets both of them wrong.
--
-- No Hopi towns are in this batch. The Hopi Reservation sits inside the Navajo
-- Nation and keeps Arizona time, so anything from Second Mesa or Kykotsmovi
-- belongs on America/Phoenix despite being surrounded by land that does not.
--
-- Five proximity flags kept, all Tombstone and Jerome being small towns that
-- put everything on one street.
--
-- 200 stops, every one with a source.

delete from public.stops
where state = 'AZ'
  and slug in (
    'goldfield-ghost-town',
    'castle-dome-mine-museum',
    'gold-king-mine-ghost-town',
    'vulture-mine-tours-vulture-city-ghost-town'
  );

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Mystery Castle', 'mystery-castle', 'roadside-oddities', 33.35679, -112.06192, 'Phoenix', 'AZ', 'Boyce Luther Gulley built this sprawling hand-made castle from stone, adobe, automobile parts and other salvaged material beginning in the 1930s. The property changed ownership in 2026, but public tours are not reliably available, so OddWay should treat it as a preservation-site/exterior stop unless official access is announced.', 'roadside', 'https://savingplaces.org/places/mystery-castle', null, 'America/Phoenix', now()),
  ('Tovrea Castle at Carraro Heights', 'tovrea-castle-at-carraro-heights', 'roadside-oddities', 33.45044, -111.97331, 'Phoenix', 'AZ', 'The tiered desert landmark often called Phoenix''s ''wedding cake'' castle rises above a cactus garden and has decades of mystery attached to its isolated appearance. Interior access is through scheduled docent tours that commonly sell out.', 'limited', 'https://tovreacastletours.com/', null, 'America/Phoenix', now()),
  ('S''edav Va''aki Museum', 'sedav-vaaki-museum', 'weird-history', 33.44603, -111.98414, 'Phoenix', 'AZ', 'This City of Phoenix museum preserves a major platform mound, portions of prehistoric irrigation canals and other evidence of the Ancestral Sonoran Desert People. The renamed site is one of the strongest places in metro Phoenix to see how much older the city is than its modern streets.', 'limited', 'https://www.phoenix.gov/parks/arts-culture-history/sedav-vaaki-museum', null, 'America/Phoenix', now()),
  ('Dreamy Draw UFO Crash Legend — Dreamy Draw Recreation Area', 'dreamy-draw-ufo-crash-legend-dreamy-draw-recreation-area', 'ufos', 33.55355, -112.03071, 'Phoenix', 'AZ', 'A long-running Phoenix legend claims the nearby mountains conceal the remains of an unusual 1940s aerial crash and that Dreamy Draw Dam was connected to a government cover story. There is no evidence establishing an extraterrestrial crash, so OddWay should frame the story strictly as local UFO folklore while routing visitors to the public recreation area.', 'open', 'https://www.phoenix.gov/parks/trails/locations/piestewa-peak', null, 'America/Phoenix', now()),
  ('Hall of Flame Fire Museum', 'hall-of-flame-fire-museum', 'museums', 33.44767, -111.95326, 'Phoenix', 'AZ', 'Rows of historic fire engines, hand-pumped apparatus and firefighting equipment turn this into one of the country''s most specialized emergency-service museums. The National Firefighting Hall of Heroes adds a darker memorial-history layer to the collection.', 'limited', 'https://hallofflame.org/', null, 'America/Phoenix', now()),
  ('Arizona Military Museum', 'arizona-military-museum', 'weird-history', 33.45737, -111.95377, 'Phoenix', 'AZ', 'Located at Papago Park Military Reservation, this museum traces Arizona military history through uniforms, vehicles, weapons and exhibits spanning territorial days through modern service. Because it sits on a military installation, visitors should check current access procedures before going.', 'limited', 'https://dema.az.gov/army-national-guard/arizona-military-museum', null, 'America/Phoenix', now()),
  ('Governor Hunt''s Tomb', 'governor-hunts-tomb', 'weird-history', 33.45116, -111.94905, 'Phoenix', 'AZ', 'Arizona''s first governor and several family members are buried beneath an enormous white pyramid overlooking Phoenix from Papago Park. The deliberately monumental tomb looks startlingly out of place against the red desert rock.', 'open', 'https://www.phoenix.gov/parks/parks/papago-park', null, 'America/Phoenix', now()),
  ('Hole-in-the-Rock — Papago Park', 'hole-in-the-rock-papago-park', 'roadside-oddities', 33.45649, -111.94526, 'Phoenix', 'AZ', 'A giant opening weathered through Papago Park sandstone creates a natural window above the desert. Archaeological evidence indicates the formation was also used by Indigenous people to track seasonal sunlight, giving the short hike both geologic and cultural interest.', 'open', 'https://www.phoenix.gov/parks/parks/papago-park', null, 'America/Phoenix', now()),
  ('Mogollon Monster — Mogollon Rim Visitor Center', 'mogollon-monster-mogollon-rim-visitor-center', 'cryptids', 34.42538, -111.33131, 'Payson', 'AZ', 'Arizona folklore describes the Mogollon Monster as a large, hairy creature associated with the forests and escarpments of the Mogollon Rim. OddWay should present the creature as regional legend and use the public visitor-center area as the lawful route point rather than sending travelers into an unspecified backcountry ''sighting'' location.', 'limited', 'https://www.fs.usda.gov/recarea/tonto/recarea/?recid=35543', null, 'America/Phoenix', now()),
  ('Arizona Falls', 'arizona-falls', 'roadside-oddities', 33.51315, -111.96463, 'Phoenix', 'AZ', 'A historic canal drop has been turned into a working hydroelectric plant wrapped in public art and pedestrian space. Water, machinery and architecture occupy the same compact site beside the Arizona Canal.', 'open', 'https://www.srpnet.com/grid-water-management/water-recreation/arizona-falls', null, 'America/Phoenix', now()),
  ('Phoenix Bat Cave', 'phoenix-bat-cave', 'roadside-oddities', 33.51474, -112.00121, 'Phoenix', 'AZ', 'Thousands of Mexican free-tailed bats use this flood-control tunnel near the Arizona Canal during the warm season, emerging around dusk in a dense stream. Visitors should remain behind fencing, stay on the public path and never enter the drainage channel or handle bats.', 'limited', 'https://www.maricopa.gov/DocumentCenter/View/76991/Phoenix-Bat-Cave-Instructions', null, 'America/Phoenix', now()),
  ('Cosanti', 'cosanti', 'roadside-oddities', 33.56717, -111.94235, 'Paradise Valley', 'AZ', 'Architect Paolo Soleri''s experimental complex uses earth-cast concrete, apses and unusual passive-solar forms that feel more like an archaeological site from the future than a conventional workshop. Artisans still cast Soleri bells on site.', 'limited', 'https://cosanti.com/', null, 'America/Phoenix', now()),
  ('Taliesin West', 'taliesin-west', 'roadside-oddities', 33.60658, -111.84516, 'Scottsdale', 'AZ', 'Frank Lloyd Wright''s desert laboratory combines low stone walls, canvas-inspired roofs and a campus that was continually modified by Wright and his apprentices. Guided and self-guided ticketed experiences provide authorized access to the UNESCO-listed site.', 'limited', 'https://franklloydwright.org/taliesin-west/', null, 'America/Phoenix', now()),
  ('McCormick-Stillman Railroad Park', 'mccormick-stillman-railroad-park', 'roadside-oddities', 33.5375, -111.92333, 'Scottsdale', 'AZ', 'A park built around real railroad equipment, miniature trains, model layouts and a narrow-gauge ride preserves rail history in an unusually hands-on setting. Historic locomotives and the Scottsdale Railroad Museum make it more than a typical city park.', 'open', 'https://www.scottsdaleaz.gov/parks/find-a-park/mccormick-stillman-railroad-park', null, 'America/Phoenix', now()),
  ('Soleri Bridge & Plaza', 'soleri-bridge-plaza', 'roadside-oddities', 33.49364, -111.92674, 'Scottsdale', 'AZ', 'Paolo Soleri''s pedestrian bridge doubles as a solar-calendar artwork, using its pylons to cast changing shadows across the site. The structure connects his architectural ideas with one of Scottsdale''s canal crossings.', 'open', 'https://scottsdalepublicart.org/work/soleri-bridge-and-plaza/', null, 'America/Phoenix', now()),
  ('Arizona Railway Museum', 'arizona-railway-museum', 'weird-history', 33.27007, -111.83638, 'Chandler', 'AZ', 'Historic passenger cars, freight equipment and locomotives fill this outdoor railroad museum in Chandler. Visitors can enter selected cars and see the scale and mechanical detail of equipment that usually survives only behind fences.', 'limited', 'https://azrymuseum.org/', null, 'America/Phoenix', now()),
  ('Commemorative Air Force Airbase Arizona Museum', 'commemorative-air-force-airbase-arizona-museum', 'weird-history', 33.46094, -111.73358, 'Mesa', 'AZ', 'Restored warbirds and military aircraft occupy working hangars at Falcon Field, with many airplanes maintained in flying condition rather than displayed as static shells. The collection makes aviation history feel mechanical and active.', 'limited', 'https://www.azcaf.org/', null, 'America/Phoenix', now()),
  ('Mesa Grande Cultural Park', 'mesa-grande-cultural-park', 'weird-history', 33.4261, -111.8456, 'Mesa', 'AZ', 'A large prehistoric platform mound and surrounding archaeological features survive in the middle of modern Mesa. Seasonal public access allows visitors to walk the protected site while learning about the Ancestral Sonoran Desert People who built it.', 'limited', 'https://www.arizonamuseumofnaturalhistory.org/mesa-grande', null, 'America/Phoenix', now()),
  ('Superstition Mountain Museum', 'superstition-mountain-museum', 'folklore', 33.44684, -111.50334, 'Apache Junction', 'AZ', 'The museum sits beneath the Superstition Mountains and interprets mining, local history and the Lost Dutchman legend. Relocated Apacheland movie-set buildings and the Elvis Memorial Chapel make the grounds especially visual.', 'limited', 'https://superstitionmountainlostdutchmanmuseum.org/', null, 'America/Phoenix', now()),
  ('Lost Dutchman State Park', 'lost-dutchman-state-park', 'folklore', 33.46338, -111.48164, 'Apache Junction', 'AZ', 'The park lies at the foot of mountains tied to one of the Southwest''s most persistent lost-mine legends. Trails provide a lawful way to experience the landscape connected with decades of treasure stories, disappearances and speculation without treating the legend as proven history.', 'open', 'https://azstateparks.com/lost-dutchman', null, 'America/Phoenix', now()),
  ('Goldfield Ghost Town', 'goldfield-ghost-town', 'weird-history', 33.45739, -111.49122, 'Apache Junction', 'AZ', 'A reconstructed mining town built around the old Goldfield district combines mine tours, historic-style buildings and Old West attractions. It is a commercialized ghost-town experience rather than an untouched abandoned settlement, but the mining landscape is real.', 'limited', 'https://goldfieldghosttown.com/', null, 'America/Phoenix', now()),
  ('Tortilla Flat', 'tortilla-flat', 'roadside-oddities', 33.52639, -111.38972, 'Tortilla Flat', 'AZ', 'This tiny former stage stop on the Apache Trail survives as a miniature roadside settlement with a saloon, general store and outsized Old West character. Its remote canyon setting makes the few remaining buildings feel far more isolated than their distance from Phoenix suggests.', 'open', 'https://www.tortillaflataz.com/', null, 'America/Phoenix', now()),
  ('World''s Smallest Museum', 'worlds-smallest-museum', 'museums', 33.29376, -111.09691, 'Superior', 'AZ', 'A tiny roadside building near Superior has long advertised itself as the World''s Smallest Museum and packs local curiosities into an intentionally miniature space. It is a classic low-budget desert roadside oddity.', 'roadside', 'https://www.worldssmallestmuseum.com/', null, 'America/Phoenix', now()),
  ('Apache Leap', 'apache-leap', 'weird-history', 33.28117, -111.07429, 'Superior', 'AZ', 'The sheer cliff east of Superior is tied to an Apache account of warriors who died here rather than be captured by U.S. troops. The landscape is culturally significant and should be viewed respectfully from lawful public areas rather than treated as a climbing novelty.', 'roadside', 'https://www.fs.usda.gov/recarea/tonto/recarea/?recid=35251', null, 'America/Phoenix', now()),
  ('McFarland State Historic Park', 'mcfarland-state-historic-park', 'weird-history', 33.03125, -111.38765, 'Florence', 'AZ', 'Arizona''s first Pinal County courthouse later served as a sheriff''s office, jail and hospital. Preserved cells and territorial-era rooms make the compact adobe building much stranger than a typical local courthouse museum.', 'limited', 'https://azstateparks.com/mcfarland', null, 'America/Phoenix', now()),
  ('Tom Mix Memorial', 'tom-mix-memorial', 'weird-history', 32.85686, -111.18826, 'Florence', 'AZ', 'A roadside marker and small monument commemorate silent-film cowboy star Tom Mix near the site of his fatal 1940 automobile crash. The lonely desert stop preserves a surprisingly specific piece of Hollywood and highway history.', 'roadside', 'https://www.visitarizona.com/directory/tom-mix-memorial/', null, 'America/Phoenix', now()),
  ('Casa Grande Ruins National Monument', 'casa-grande-ruins-national-monument', 'weird-history', 32.99701, -111.53207, 'Coolidge', 'AZ', 'The enormous four-story Great House and surrounding compound were built by Ancestral Sonoran Desert people centuries before modern Arizona. A protective steel canopy now creates an unusual architectural shell over the ancient earthen structure.', 'open', 'https://www.nps.gov/cagr/', null, 'America/Phoenix', now()),
  ('Casa Grande Neon Sign Park', 'casa-grande-neon-sign-park', 'roadside-oddities', 32.87896, -111.75434, 'Casa Grande', 'AZ', 'Restored motel, restaurant and business signs glow together in a downtown park built specifically to preserve Casa Grande''s disappearing roadside neon. The collection is most dramatic after dark when the signs are illuminated.', 'open', 'https://neonsignpark.com/', null, 'America/Phoenix', now()),
  ('Besh-Ba-Gowah Archaeological Park', 'besh-ba-gowah-archaeological-park', 'weird-history', 33.39484, -110.78691, 'Globe', 'AZ', 'A partially reconstructed Salado pueblo allows visitors to walk through stone rooms and see artifacts from a settlement occupied roughly seven centuries ago. The site places substantial archaeology immediately inside modern Globe.', 'limited', 'https://www.globeaz.gov/besh-ba-gowah', null, 'America/Phoenix', now()),
  ('Old Dominion Historic Mine Park', 'old-dominion-historic-mine-park', 'weird-history', 33.41489, -110.78723, 'Globe', 'AZ', 'Trails and interpretive exhibits wind through the remains of Globe''s Old Dominion copper mine, including foundations, equipment and mining structures. It turns an industrial ruin into a controlled public history park instead of an unsafe abandoned-mine destination.', 'open', 'https://www.olddominionminepark.org/', null, 'America/Phoenix', now()),
  ('Bullion Plaza Cultural Center & Museum', 'bullion-plaza-cultural-center-museum', 'museums', 33.39398, -110.87949, 'Miami', 'AZ', 'A former 1920s school now holds exhibits on mining, regional history and the communities built around Arizona copper. The building''s survival inside a working mining town gives the museum unusually direct context.', 'limited', 'https://bullionplazamuseum.org/', null, 'America/Phoenix', now()),
  ('Biosphere 2', 'biosphere-2', 'roadside-oddities', 32.57889, -110.85056, 'Oracle', 'AZ', 'This vast sealed-glass research complex became famous for experiments in which crews attempted to live inside a closed artificial ecosystem. Visitors can now tour the giant greenhouse biomes, mechanical systems and spaces tied to one of the strangest scientific experiments of the 1990s.', 'limited', 'https://biosphere2.org/', null, 'America/Phoenix', now()),
  ('Kannally Ranch House — Oracle State Park', 'kannally-ranch-house-oracle-state-park', 'roadside-oddities', 32.60765, -110.73256, 'Oracle', 'AZ', 'The Mediterranean-Revival Kannally Ranch House stands unexpectedly in high-desert ranch country and preserves rooms, artwork and family history from an early twentieth-century cattle operation. It is the architectural centerpiece of Oracle State Park.', 'limited', 'https://azstateparks.com/oracle', null, 'America/Phoenix', now()),
  ('Titan Missile Museum', 'titan-missile-museum', 'weird-history', 31.90336, -110.99902, 'Green Valley', 'AZ', 'The only publicly accessible Titan II missile silo preserved as a museum lets visitors descend into a former nuclear launch complex. The control room, blast doors and missile itself make the Cold War feel unnervingly physical.', 'limited', 'https://titanmissilemuseum.org/', null, 'America/Phoenix', now()),
  ('Pima Air & Space Museum', 'pima-air-space-museum', 'weird-history', 32.14117, -110.86872, 'Tucson', 'AZ', 'Hundreds of aircraft occupy hangars and acres of desert, from bombers and experimental machines to space-related artifacts. The scale and density of obsolete flying machines make the museum one of Arizona''s strongest technology-oddity stops.', 'limited', 'https://pimaair.org/', null, 'America/Phoenix', now()),
  ('390th Memorial Museum', '390th-memorial-museum', 'weird-history', 32.14063, -110.87207, 'Tucson', 'AZ', 'A museum-within-the-museum at the Pima Air & Space campus centers on the 390th Bomb Group and its B-17 crews. Personal artifacts and a restored bomber give the site a narrower, human-scale counterpart to the enormous aircraft collection outside.', 'limited', 'https://390th.org/', null, 'America/Phoenix', now()),
  ('Arizona-Sonora Desert Museum', 'arizona-sonora-desert-museum', 'museums', 32.24272, -111.16631, 'Tucson', 'AZ', 'Part zoo, botanical garden, aquarium and natural-history museum, this sprawling institution is devoted almost entirely to the Sonoran Desert. Underground geology displays, desert animals and cactus landscapes make it far stranger than a conventional zoo.', 'limited', 'https://www.desertmuseum.org/', null, 'America/Phoenix', now()),
  ('Mission San Xavier del Bac', 'mission-san-xavier-del-bac', 'roadside-oddities', 32.11626, -111.00057, 'Tucson', 'AZ', 'The brilliant white eighteenth-century mission rises from the Tohono O''odham Nation south of Tucson with an ornate interior that sharply contrasts with the desert around it. It remains an active Catholic parish and culturally significant place, so visitors should follow church and community rules.', 'limited', 'https://www.sanxaviermission.org/', null, 'America/Phoenix', now()),
  ('Presidio San Agustín del Tucson Museum', 'presidio-san-agustin-del-tucson-museum', 'weird-history', 32.22434, -110.97698, 'Tucson', 'AZ', 'A reconstructed section of Tucson''s Spanish presidio uses adobe walls, archaeological remains and living-history demonstrations to show what the fortified settlement looked like before the modern city covered it. The contrast with downtown Tucson is the point.', 'limited', 'https://tucsonpresidio.com/', null, 'America/Phoenix', now()),
  ('El Tiradito Wishing Shrine', 'el-tiradito-wishing-shrine', 'folklore', 32.21846, -110.97436, 'Tucson', 'AZ', 'This small adobe shrine is dedicated to a figure remembered through several conflicting tragic legends and is famous for candles, notes and wishes left by visitors. It is a functioning community devotional site, so OddWay should emphasize respectful behavior rather than paranormal spectacle.', 'open', 'https://www.visittucson.org/listing/el-tiradito-wishing-shrine/775/', null, 'America/Phoenix', now()),
  ('Hotel Congress', 'hotel-congress', 'haunted', 32.22284, -110.96664, 'Tucson', 'AZ', 'The 1919 hotel is tied to Tucson nightlife, the capture of John Dillinger''s gang and decades of ghost stories associated with its old rooms and hallways. It remains an operating hotel, restaurant and music venue rather than an abandoned haunt.', 'open', 'https://hotelcongress.com/', null, 'America/Phoenix', now()),
  ('Alfie Norville Gem & Mineral Museum', 'alfie-norville-gem-mineral-museum', 'museums', 32.2201, -110.97126, 'Tucson', 'AZ', 'This University of Arizona museum fills galleries with meteorites, fluorescent minerals, gemstones and spectacular mineral specimens. Tucson''s global gem-show culture makes the concentrated geology collection especially fitting.', 'limited', 'https://gemandmineralmuseum.arizona.edu/', null, 'America/Phoenix', now()),
  ('Arizona State Museum', 'arizona-state-museum', 'weird-history', 32.23209, -110.95273, 'Tucson', 'AZ', 'The University of Arizona museum holds major archaeological and Indigenous collections, including one of the world''s largest collections of Southwest Native pottery. Visitors should treat culturally sensitive material as history and heritage rather than curiosities.', 'limited', 'https://statemuseum.arizona.edu/', null, 'America/Phoenix', now()),
  ('The Mini Time Machine Museum of Miniatures', 'the-mini-time-machine-museum-of-miniatures', 'museums', 32.28594, -110.89906, 'Tucson', 'AZ', 'Entire houses, rooms, fantasy scenes and historical environments are recreated at tiny scale inside this museum devoted to miniatures. The obsessive detail makes ordinary objects feel uncanny when reduced to dollhouse proportions.', 'limited', 'https://theminitimemachine.org/', null, 'America/Phoenix', now()),
  ('Ignite Sign Art Museum', 'ignite-sign-art-museum', 'roadside-oddities', 32.25054, -110.90361, 'Tucson', 'AZ', 'Restored neon, hand-painted signs and commercial sign-making artifacts fill this small Tucson museum. Many pieces are displayed lit, turning old advertising hardware into a concentrated room of glowing roadside history.', 'limited', 'https://www.ignitesignartmuseum.com/', null, 'America/Phoenix', now()),
  ('Valley of the Moon', 'valley-of-the-moon', 'roadside-oddities', 32.27263, -110.93664, 'Tucson', 'AZ', 'Built beginning in the 1920s, this hand-made fantasy landscape contains winding paths, grottoes, towers, tunnels and theatrical spaces created from rock and concrete. Public access is tied to tours, performances and scheduled events rather than daily open-gate visitation.', 'limited', 'https://www.tucsonvalleyofthemoon.com/', null, 'America/Phoenix', now()),
  ('Tucson Rodeo Parade Museum', 'tucson-rodeo-parade-museum', 'museums', 32.18678, -110.96856, 'Tucson', 'AZ', 'Historic wagons, coaches and parade equipment preserve the machinery behind Tucson''s long-running rodeo parade. The collection functions almost like a warehouse of pre-automobile transportation frozen in working order.', 'limited', 'https://www.tucsonrodeoparade.com/museum', null, 'America/Phoenix', now()),
  ('DeGrazia Gallery in the Sun', 'degrazia-gallery-in-the-sun', 'roadside-oddities', 32.30787, -110.91628, 'Tucson', 'AZ', 'Artist Ted DeGrazia built this adobe gallery complex with desert materials, murals and an intentionally rough handcrafted aesthetic. The chapel, gallery rooms and surrounding cactus landscape feel like a self-contained artist-built village.', 'limited', 'https://degrazia.org/', null, 'America/Phoenix', now()),
  ('Garden of Gethsemane', 'garden-of-gethsemane', 'roadside-oddities', 32.21848, -110.98572, 'Tucson', 'AZ', 'Felix Lucero created a small group of concrete religious sculptures after surviving World War I, and the figures now occupy a riverside city park. Their weathered handmade appearance gives the site the feeling of a preserved personal vision rather than formal public statuary.', 'open', 'https://www.tucsonaz.gov/Departments/Parks-and-Recreation/Parks/Garden-of-Gethsemane', null, 'America/Phoenix', now()),
  ('Old Tucson', 'old-tucson', 'weird-history', 32.24713, -111.12763, 'Tucson', 'AZ', 'Originally built as a movie set, Old Tucson accumulated saloons, streets and false-front buildings used in decades of Western productions. The attraction lets visitors walk through a fabricated Old West that became historic in its own right.', 'limited', 'https://oldtucson.com/', null, 'America/Phoenix', now()),
  ('Colossal Cave Mountain Park', 'colossal-cave-mountain-park', 'roadside-oddities', 32.06445, -110.62946, 'Vail', 'AZ', 'Guided tours enter a dry limestone cave system of passages, formations and historic graffiti east of Tucson. The cave also carries stories involving miners, outlaws and Depression-era improvements built by the Civilian Conservation Corps.', 'limited', 'https://colossalcave.com/', null, 'America/Phoenix', now()),
  ('Rattlesnake Bridge', 'rattlesnake-bridge', 'roadside-oddities', 32.21611, -110.90828, 'Tucson', 'AZ', 'This pedestrian bridge is shaped like a giant diamondback rattlesnake, with users entering through the open jaws and exiting near a sculpted tail. Sound effects and scaled details turn ordinary infrastructure into one of Tucson''s most literal pieces of creature architecture.', 'open', 'https://artsfoundtucson.org/public-art/', null, 'America/Phoenix', now()),
  ('Sentinel Peak ''A'' Mountain', 'sentinel-peak-a-mountain', 'roadside-oddities', 32.21422, -110.9923, 'Tucson', 'AZ', 'A huge white ''A'' painted on Sentinel Peak has overlooked Tucson for more than a century and is periodically recolored during civic events. The summit also provides an easy route point for viewing the city''s geology and urban history.', 'open', 'https://www.tucsonaz.gov/Departments/Parks-and-Recreation/Parks/Sentinel-Peak-Park-A-Mountain', null, 'America/Phoenix', now()),
  ('Tumacácori National Historical Park', 'tumacacori-national-historical-park', 'weird-history', 31.5679, -111.05121, 'Tumacacori', 'AZ', 'Ruins and preserved buildings document Spanish mission communities and the complicated colonial history of the Santa Cruz Valley. The unfinished church and surviving adobe structures create one of southern Arizona''s most atmospheric historic landscapes.', 'open', 'https://www.nps.gov/tuma/', null, 'America/Phoenix', now()),
  ('Tubac Presidio State Historic Park', 'tubac-presidio-state-historic-park', 'weird-history', 31.61206, -111.04665, 'Tubac', 'AZ', 'Arizona''s first state historic park preserves archaeological remains of a Spanish presidio, a territorial schoolhouse, printing history and artifacts from centuries of settlement. Layers of structures overlap in a compact downtown site.', 'limited', 'https://azstateparks.com/tubac', null, 'America/Phoenix', now()),
  ('Kartchner Caverns State Park', 'kartchner-caverns-state-park', 'roadside-oddities', 31.83702, -110.34728, 'Benson', 'AZ', 'A living cave discovered in 1974 was kept secret for years while plans were developed to protect its delicate formations. Guided tours reveal enormous rooms and active mineral growth under strict conservation rules.', 'limited', 'https://azstateparks.com/kartchner', null, 'America/Phoenix', now()),
  ('Amerind Museum', 'amerind-museum', 'weird-history', 32.0129, -110.07813, 'Dragoon', 'AZ', 'Set among the boulders of Texas Canyon, the Amerind preserves archaeology, art and Indigenous cultural material from across the Americas. The remote campus and unusual rock landscape make the trip feel like entering a private research outpost.', 'limited', 'https://www.amerind.org/', null, 'America/Phoenix', now()),
  ('The Thing?', 'the-thing', 'roadside-oddities', 32.05273, -110.07708, 'Dragoon', 'AZ', 'Billboards across Interstate 10 build suspense for miles before travelers reach this classic mystery attraction and its deliberately strange museum displays. The current version mixes roadside spectacle, aliens, dinosaurs and a heavily theatrical answer to the question on the signs.', 'limited', 'https://bowlinsthething.com/', null, 'America/Phoenix', now()),
  ('Cochise Stronghold', 'cochise-stronghold', 'weird-history', 31.92164, -109.9707, 'Dragoon', 'AZ', 'Granite formations in the Dragoon Mountains sheltered Apache leader Cochise and his followers during conflict with the United States. Trails cross dramatic boulder fields, but the site should be treated as a culturally significant historic landscape rather than a hideout-themed playground.', 'open', 'https://www.fs.usda.gov/recarea/coronado/recarea/?recid=25354', null, 'America/Phoenix', now()),
  ('Gammons Gulch Movie Set & Museum', 'gammons-gulch-movie-set-museum', 'weird-history', 31.97778, -110.30911, 'Benson', 'AZ', 'A private Old West movie-set town assembled from historic buildings, props and salvaged materials sits in the desert north of Benson. Visits are scheduled, giving travelers a controlled way to explore a place that looks like an abandoned settlement but is actually a maintained film location.', 'limited', 'https://gammonsgulch.com/', null, 'America/Phoenix', now()),
  ('Fort Bowie National Historic Site', 'fort-bowie-national-historic-site', 'weird-history', 32.15665, -109.45128, 'Bowie', 'AZ', 'Ruins along a desert trail mark the nineteenth-century fort at the center of U.S.-Apache conflict and the struggle for control of Apache Pass. Reaching the main site normally requires a hike, so access is more demanding than a roadside museum.', 'limited', 'https://www.nps.gov/fobo/', null, 'America/Phoenix', now()),
  ('Chiricahua National Monument — Echo Canyon', 'chiricahua-national-monument-echo-canyon', 'roadside-oddities', 32.01037, -109.31216, 'Willcox', 'AZ', 'Thousands of rhyolite pinnacles, balanced rocks and narrow passages create the ''wonderland of rocks'' in the Chiricahua Mountains. Echo Canyon trails bring visitors directly among formations that look constructed despite being entirely geologic.', 'open', 'https://www.nps.gov/chir/', null, 'America/Phoenix', now()),
  ('Rex Allen Arizona Cowboy Museum', 'rex-allen-arizona-cowboy-museum', 'museums', 32.25234, -109.83284, 'Willcox', 'AZ', 'This compact museum is devoted to Willcox-born singing cowboy Rex Allen, preserving costumes, photographs, records and movie memorabilia. A nearby statue and the grave of Allen''s horse Koko add to the town''s unusually specific cowboy-celebrity landscape.', 'limited', 'https://www.rexallenmuseum.org/', null, 'America/Phoenix', now()),
  ('Willcox Playa', 'willcox-playa', 'roadside-oddities', 32.14285, -109.85088, 'Willcox', 'AZ', 'The broad dry-lake basin east of Willcox becomes an important winter gathering area for sandhill cranes and other birds. Seasonal viewing turns an apparently empty desert playa into a moving wildlife spectacle.', 'limited', 'https://www.azgfd.com/location/willcox-playa-wildlife-area/', null, 'America/Phoenix', now()),
  ('Gadsden Hotel', 'gadsden-hotel', 'haunted', 31.34497, -109.55478, 'Douglas', 'AZ', 'A marble staircase, stained glass and grand lobby survive inside this 1907 border-town hotel, which rebuilt after a major fire. Local stories of unexplained footsteps and apparitions add paranormal lore to an operating historic hotel.', 'open', 'https://thegadsdenhotel.com/', null, 'America/Phoenix', now()),
  ('Slaughter Ranch Museum', 'slaughter-ranch-museum', 'weird-history', 31.34969, -109.2792, 'Douglas', 'AZ', 'The restored ranch of lawman John Slaughter sits near the international border with historic buildings, ponds and artifacts from a remote cattle operation. Its isolation and connection to a violent frontier career give it a strong dark-history atmosphere.', 'limited', 'https://www.slaughterranch.com/', null, 'America/Phoenix', now()),
  ('Fort Huachuca Museum', 'fort-huachuca-museum', 'weird-history', 31.55528, -110.34968, 'Fort Huachuca', 'AZ', 'The U.S. Army museum interprets Fort Huachuca''s frontier history, Buffalo Soldiers, military intelligence and later missions. Because it is inside an active Army installation, adult visitors without qualifying military identification should expect current security screening requirements.', 'limited', 'https://history.army.mil/Army-Museum-Enterprise/Find-an-Army-Museum/Fort-Huachuca-Museum-and-Annex/', null, 'America/Phoenix', now()),
  ('Coronado Cave', 'coronado-cave', 'roadside-oddities', 31.34559, -110.25629, 'Hereford', 'AZ', 'A large undeveloped limestone cavern inside Coronado National Memorial can be reached by a steep trail and explored without built lighting. Visitors need appropriate lights and should follow NPS cave guidance rather than treating it like a commercial show cave.', 'limited', 'https://www.nps.gov/coro/planyourvisit/coronado-cave.htm', null, 'America/Phoenix', now()),
  ('Queen Mine Tour', 'queen-mine-tour', 'weird-history', 31.44139, -109.91496, 'Bisbee', 'AZ', 'Visitors ride underground on a former mining train into one of Bisbee''s historic copper mines while retired miners explain tools, working conditions and ore extraction. The authorized tour provides the abandoned-mine atmosphere without illegal entry.', 'limited', 'https://queenminetour.com/', null, 'America/Phoenix', now()),
  ('Bisbee Mining & Historical Museum', 'bisbee-mining-historical-museum', 'museums', 31.44231, -109.91548, 'Bisbee', 'AZ', 'A Smithsonian-affiliated museum inside a former mining-company building interprets the boomtown, its labor history and the enormous underground industry beneath Bisbee. Exhibits connect the picturesque streets outside to the harsh mining economy that created them.', 'limited', 'https://bisbeemuseum.org/', null, 'America/Phoenix', now()),
  ('Copper Queen Hotel', 'copper-queen-hotel', 'haunted', 31.44308, -109.91588, 'Bisbee', 'AZ', 'Arizona''s long-running Copper Queen Hotel has accumulated stories of apparitions associated with former guests and employees. It remains an active hotel, making the experience lawful and grounded in a preserved historic building rather than an abandoned property.', 'open', 'https://www.copperqueen.com/', null, 'America/Phoenix', now()),
  ('Erie Street — Lowell Historic District', 'erie-street-lowell-historic-district', 'weird-history', 31.42033, -109.88631, 'Bisbee', 'AZ', 'A surviving strip of Lowell preserves vintage storefronts, old cars, gas pumps and mid-century signs after much of the community was consumed by the expanding open-pit mine. The streetscape looks deliberately staged even though it grew out of a real displaced neighborhood.', 'open', 'https://www.discoverbisbee.com/', null, 'America/Phoenix', now()),
  ('Lavender Pit Overlook', 'lavender-pit-overlook', 'roadside-oddities', 31.43319, -109.90131, 'Bisbee', 'AZ', 'A public overlook faces the immense terraced Lavender Pit, where copper mining carved a brightly colored artificial canyon beside Bisbee. The engineered void makes the scale of the town''s mining history immediately visible.', 'open', 'https://www.discoverbisbee.com/', null, 'America/Phoenix', now()),
  ('Muheim Heritage House', 'muheim-heritage-house', 'roadside-oddities', 31.44433, -109.91767, 'Bisbee', 'AZ', 'This hillside home preserves early Bisbee domestic life and a panoramic view across the old mining town. Its steep setting and period rooms make it a compact companion to the city''s more industrial attractions.', 'limited', 'https://bisbeemuseum.org/muheim-heritage-house/', null, 'America/Phoenix', now()),
  ('Warren Ballpark', 'warren-ballpark', 'weird-history', 31.4147, -109.8784, 'Bisbee', 'AZ', 'Opened in 1909, Warren Ballpark is one of the oldest continuously used baseball grounds in the United States and is tied to mining-company teams, labor history and the 1917 Bisbee Deportation era. Check event access before planning to enter the field or stands.', 'limited', 'https://www.friendsofwarrenballpark.com/', null, 'America/Phoenix', now()),
  ('Bird Cage Theatre', 'bird-cage-theatre', 'haunted', 31.71439, -110.06729, 'Tombstone', 'AZ', 'The former theater, saloon and gambling hall preserves bullet marks, gaming equipment and rooms associated with Tombstone''s boom years. Its violent history has also made it one of the town''s best-known paranormal-tour destinations.', 'limited', 'https://tombstonebirdcage.com/', null, 'America/Phoenix', now()),
  ('O.K. Corral', 'o-k-corral', 'weird-history', 31.71374, -110.0679, 'Tombstone', 'AZ', 'The famous 1881 gunfight occurred in a small lot near this site and lasted only seconds, but it became one of the defining myths of the American West. Exhibits and reenactments interpret the event inside the modern attraction.', 'limited', 'https://ok-corral.com/', null, 'America/Phoenix', now()),
  ('Boothill Graveyard', 'boothill-graveyard', 'weird-history', 31.72353, -110.06714, 'Tombstone', 'AZ', 'Graves of miners, outlaws, townspeople and victims of violence fill Tombstone''s famous frontier cemetery. Many markers have been reconstructed over time, so OddWay should distinguish the cemetery''s real history from later tourist legend.', 'limited', 'https://www.boothillgraves.com/', null, 'America/Phoenix', now()),
  ('Good Enough Mine Tour', 'good-enough-mine-tour', 'weird-history', 31.71284, -110.06863, 'Tombstone', 'AZ', 'Guided tours descend into workings of a silver mine that helped fuel Tombstone''s boom. Timbering, narrow passages and mining equipment provide an underground counterpoint to the gunfight history above ground.', 'limited', 'https://tombstonegoodenough.com/', null, 'America/Phoenix', now()),
  ('Tombstone Courthouse State Historic Park', 'tombstone-courthouse-state-historic-park', 'weird-history', 31.71233, -110.07007, 'Tombstone', 'AZ', 'The 1882 courthouse contains courtroom displays, gallows-related material, weapons and exhibits on crime and punishment in territorial Tombstone. A reconstructed gallows in the yard makes the site''s justice history particularly tangible.', 'limited', 'https://azstateparks.com/tombstone', null, 'America/Phoenix', now()),
  ('Rose Tree Museum', 'rose-tree-museum', 'roadside-oddities', 31.71297, -110.06676, 'Tombstone', 'AZ', 'A massive Lady Banks rose planted in the 1880s spreads over an enormous trellis behind this small museum and is promoted as the world''s largest rose bush. The living plant turns an ordinary historic courtyard into a bizarre overhead canopy.', 'limited', 'https://tombstonerosetree.com/', null, 'America/Phoenix', now()),
  ('Tombstone Epitaph Museum', 'tombstone-epitaph-museum', 'weird-history', 31.71355, -110.06614, 'Tombstone', 'AZ', 'The office of the newspaper that reported on Tombstone''s violent boom years preserves printing equipment and exhibits about frontier journalism. Visitors can see how legends now associated with the town were first turned into contemporary news.', 'limited', 'https://tombstoneepitaph.com/', null, 'America/Phoenix', now()),
  ('Big Nose Kate''s Saloon', 'big-nose-kates-saloon', 'haunted', 31.7139, -110.06709, 'Tombstone', 'AZ', 'This modern saloon occupies a historic downtown building and leans heavily into Tombstone lore connected with Big Nose Kate, Doc Holliday and alleged hauntings. Treat ghost claims as entertainment and local legend rather than documented fact.', 'open', 'https://bignosekates.info/', null, 'America/Phoenix', now()),
  ('Gleeson Jail & Ghost Town', 'gleeson-jail-ghost-town', 'weird-history', 31.73255, -109.82959, 'Gleeson', 'AZ', 'A restored concrete jail anchors the remains of the former mining settlement of Gleeson, where scattered ruins and foundations survive along the road. Much surrounding land is private, so visitors should stay on lawful roads and areas explicitly open to the public.', 'limited', 'https://www.gleesonarizona.com/', null, 'America/Phoenix', now()),
  ('Fairbank Historic Townsite', 'fairbank-historic-townsite', 'weird-history', 31.72264, -110.18925, 'Fairbank', 'AZ', 'The Bureau of Land Management preserves buildings and foundations from a railroad town that served nearby Tombstone. Trails and interpretive signs provide an authorized ghost-town experience without encouraging entry into unstable private ruins.', 'open', 'https://www.blm.gov/visit/fairbank-historic-townsite', null, 'America/Phoenix', now()),
  ('Vulture City Ghost Town', 'vulture-city-ghost-town', 'weird-history', 33.8205, -112.83827, 'Wickenburg', 'AZ', 'Restored buildings and mining structures preserve the settlement that grew around the Vulture Mine, one of Arizona''s most important gold operations. Tours and paranormal events provide legal access to a site that still looks isolated enough to feel abandoned.', 'limited', 'https://vulturecityghosttown.com/', null, 'America/Phoenix', now()),
  ('Jail Tree', 'jail-tree', 'weird-history', 33.96883, -112.72967, 'Wickenburg', 'AZ', 'Local tradition says prisoners were chained to this mesquite tree before Wickenburg had a proper jail. The tree survives as a tiny downtown landmark illustrating the improvised infrastructure of an early desert town.', 'open', 'https://outwickenburgway.com/', null, 'America/Phoenix', now()),
  ('Shrine of St. Joseph of the Mountains', 'shrine-of-st-joseph-of-the-mountains', 'roadside-oddities', 34.22104, -112.75005, 'Yarnell', 'AZ', 'Stone paths climb a hillside past life-size religious sculptures depicting the Stations of the Cross and other scenes. The handmade mountain setting gives the shrine an unusually immersive folk-art character.', 'limited', 'https://www.stjoseph-shrine.org/', null, 'America/Phoenix', now()),
  ('Granite Mountain Hotshots Memorial State Park', 'granite-mountain-hotshots-memorial-state-park', 'weird-history', 34.2251, -112.77815, 'Yarnell', 'AZ', 'A steep trail leads to overlooks and memorials honoring the 19 Granite Mountain Hotshots who died in the 2013 Yarnell Hill Fire. This is a solemn memorial landscape rather than a disaster spectacle, and visitors should approach it accordingly.', 'open', 'https://azstateparks.com/hotshots', null, 'America/Phoenix', now()),
  ('Arcosanti', 'arcosanti', 'roadside-oddities', 34.34297, -112.10462, 'Mayer', 'AZ', 'Paolo Soleri''s experimental ''arcology'' has been under construction in the high desert since 1970, combining apartments, workshops, vaults and communal spaces into a compact futuristic settlement. Tours explain both the architecture and the incomplete social experiment behind it.', 'limited', 'https://www.arcosanti.org/', null, 'America/Phoenix', now()),
  ('Jerome State Historic Park', 'jerome-state-historic-park', 'weird-history', 34.75344, -112.1111, 'Jerome', 'AZ', 'The Douglas Mansion overlooks Jerome''s enormous mining landscape with exhibits on copper, geology and the town''s boom-and-collapse cycle. From the grounds, visitors can see how precariously the settlement clings to Cleopatra Hill.', 'limited', 'https://azstateparks.com/jerome', null, 'America/Phoenix', now()),
  ('Jerome Sliding Jail', 'jerome-sliding-jail', 'roadside-oddities', 34.74847, -112.11428, 'Jerome', 'AZ', 'Ground movement from mining caused Jerome''s concrete jail building to shift downhill from its original foundation. The displaced structure now sits as a roadside monument to just how unstable the mining town became.', 'open', 'https://jerome.az.gov/', null, 'America/Phoenix', now()),
  ('Audrey Headframe Park', 'audrey-headframe-park', 'roadside-oddities', 34.7567, -112.11731, 'Jerome', 'AZ', 'A glass-covered shaft lets visitors look straight down into the 1,900-foot Audrey mine shaft beside massive surviving headframe machinery. Railings and a protected viewing area turn an otherwise dangerous mine feature into a controlled public stop.', 'open', 'https://jerome.az.gov/', null, 'America/Phoenix', now()),
  ('Gold King Mine & Ghost Town', 'gold-king-mine-ghost-town', 'weird-history', 34.76328, -112.12335, 'Jerome', 'AZ', 'A collection of mining machinery, trucks, buildings and odd mechanical projects occupies an old mining site above Jerome. Rusted equipment and homemade contraptions make it as much an industrial junkyard museum as a ghost-town attraction.', 'limited', 'https://goldkingmineghosttown.com/', null, 'America/Phoenix', now()),
  ('Jerome Mine Museum', 'jerome-mine-museum', 'museums', 34.74869, -112.11352, 'Jerome', 'AZ', 'The small downtown museum preserves mining equipment, photographs and objects from Jerome''s copper era. Its concentrated collection helps decode the ruins, shafts and industrial fragments scattered throughout town.', 'limited', 'https://jeromechamber.com/', null, 'America/Phoenix', now()),
  ('Jerome Grand Hotel', 'jerome-grand-hotel', 'haunted', 34.75142, -112.11122, 'Jerome', 'AZ', 'Jerome''s former hospital now operates as a hotel and is one of Arizona''s most persistent haunted-hotel destinations. Stories of apparitions and unexplained sounds are part of the property''s reputation, but OddWay should present them as reported lore.', 'open', 'https://jeromegrandhotel.net/', null, 'America/Phoenix', now()),
  ('Connor Hotel', 'connor-hotel', 'haunted', 34.74855, -112.1144, 'Jerome', 'AZ', 'The Connor reopened as lodging after decades in which the upper floors sat unused following Jerome''s mining decline. Guests and ghost tours regularly attach paranormal stories to the historic rooms above the Spirit Room bar.', 'open', 'https://connorhotel.com/', null, 'America/Phoenix', now()),
  ('Verde Canyon Railroad', 'verde-canyon-railroad', 'roadside-oddities', 34.77118, -112.05958, 'Clarkdale', 'AZ', 'Passenger trains travel through a canyon otherwise difficult to access, passing old rail infrastructure, red-rock cliffs and remnants of the mining-era route. Vintage-style cars make the transportation itself part of the attraction.', 'limited', 'https://verdecanyonrr.com/', null, 'America/Phoenix', now()),
  ('Arizona Copper Art Museum', 'arizona-copper-art-museum', 'museums', 34.77192, -112.05775, 'Clarkdale', 'AZ', 'An old schoolhouse contains thousands of objects made from copper, ranging from cookware and military art to decorative architecture. The narrow material focus is especially fitting in a town built around the copper industry.', 'limited', 'https://www.copperartmuseum.com/', null, 'America/Phoenix', now()),
  ('Tuzigoot National Monument', 'tuzigoot-national-monument', 'weird-history', 34.77289, -112.02876, 'Clarkdale', 'AZ', 'A hilltop pueblo of stone rooms rises above the Verde Valley, preserving a settlement built by people archaeologists call the Sinagua. Trails climb through the protected ruins to broad views of the valley and nearby mining towns.', 'open', 'https://www.nps.gov/tuzi/', null, 'America/Phoenix', now()),
  ('Montezuma Castle National Monument', 'montezuma-castle-national-monument', 'weird-history', 34.6116, -111.83499, 'Camp Verde', 'AZ', 'A five-story cliff dwelling sits high in a limestone recess above Beaver Creek. The site is protected and cannot be entered, but a short public trail gives a clear view of one of Arizona''s most visually dramatic preserved dwellings.', 'open', 'https://www.nps.gov/moca/', null, 'America/Phoenix', now()),
  ('Montezuma Well', 'montezuma-well', 'roadside-oddities', 34.64913, -111.75235, 'Camp Verde', 'AZ', 'A large limestone sink filled with spring water supports an unusual ecosystem and is surrounded by prehistoric dwellings and irrigation features. The combination of geology, archaeology and persistent spring flow makes the site unlike a normal desert pond.', 'open', 'https://www.nps.gov/moca/planyourvisit/montezuma-well.htm', null, 'America/Phoenix', now()),
  ('Fort Verde State Historic Park', 'fort-verde-state-historic-park', 'weird-history', 34.56522, -111.85342, 'Camp Verde', 'AZ', 'Original 1870s military buildings survive from a fort associated with U.S. campaigns against Indigenous peoples in central Arizona. Furnished rooms and exhibits preserve a difficult period of frontier military history in unusually intact surroundings.', 'limited', 'https://azstateparks.com/fort-verde', null, 'America/Phoenix', now()),
  ('V Bar V Heritage Site', 'v-bar-v-heritage-site', 'weird-history', 34.67014, -111.73561, 'Rimrock', 'AZ', 'More than a thousand petroglyphs cover sandstone panels at this protected Verde Valley site. Access follows posted schedules and a short trail, and visitors should never touch, trace or alter the rock art.', 'limited', 'https://www.fs.usda.gov/recarea/coconino/recarea/?recid=55424', null, 'America/Phoenix', now()),
  ('Palatki Heritage Site', 'palatki-heritage-site', 'weird-history', 34.9154, -111.89712, 'Sedona', 'AZ', 'Cliff dwellings and pictographs survive beneath red-rock alcoves west of Sedona. Reservations and Forest Service controls help protect the archaeological site, so travelers should use official access rather than improvised back-road routes.', 'limited', 'https://www.fs.usda.gov/recarea/coconino/recarea/?recid=55368', null, 'America/Phoenix', now()),
  ('Honanki Heritage Site', 'honanki-heritage-site', 'weird-history', 34.93334, -111.94083, 'Sedona', 'AZ', 'Stone dwelling remains and extensive pictographs occupy a protected red-rock alcove in the Coconino National Forest. Road conditions and site rules can change, making this a check-ahead archaeological stop.', 'limited', 'https://www.fs.usda.gov/recarea/coconino/recarea/?recid=55336', null, 'America/Phoenix', now()),
  ('Chapel of the Holy Cross', 'chapel-of-the-holy-cross', 'roadside-oddities', 34.83214, -111.76686, 'Sedona', 'AZ', 'A modern chapel appears embedded directly into Sedona''s red rock, with a huge cross dominating the glass front. The dramatic architecture is still an active religious site, so visitors should respect worship and posted access rules.', 'limited', 'https://chapeloftheholycross.com/', null, 'America/Phoenix', now()),
  ('Amitabha Stupa and Peace Park', 'amitabha-stupa-and-peace-park', 'roadside-oddities', 34.86874, -111.80543, 'Sedona', 'AZ', 'A 36-foot Buddhist stupa and prayer-wheel garden occupy a quiet red-rock setting in West Sedona. It is an active sacred space open to visitors, not a novelty attraction, and should be treated accordingly.', 'open', 'https://amitabha.stupa.org/', null, 'America/Phoenix', now()),
  ('Airport Mesa Vortex', 'airport-mesa-vortex', 'folklore', 34.8558, -111.77975, 'Sedona', 'AZ', 'Airport Mesa is one of the places most commonly identified in Sedona''s modern ''vortex'' belief tradition. OddWay should describe the energy claims as spiritual/New Age interpretation rather than measurable fact while routing visitors to established public trails and overlooks.', 'open', 'https://www.fs.usda.gov/recarea/coconino/recarea/?recid=54892', null, 'America/Phoenix', now()),
  ('Bell Rock', 'bell-rock', 'folklore', 34.80555, -111.76633, 'Sedona', 'AZ', 'The bell-shaped red-rock formation is both a distinctive geologic landmark and one of Sedona''s most famous claimed vortex locations. Trails offer public access, while the supernatural-energy reputation should be framed as belief and local tourism lore.', 'open', 'https://www.fs.usda.gov/recarea/coconino/recarea/?recid=55248', null, 'America/Phoenix', now()),
  ('Boynton Canyon Vortex', 'boynton-canyon-vortex', 'folklore', 34.90729, -111.84917, 'Sedona', 'AZ', 'Boynton Canyon combines a dramatic box-canyon hike with one of Sedona''s best-known vortex traditions. The landscape is real; claims of concentrated spiritual energy are subjective and should be presented as part of modern local culture.', 'open', 'https://www.fs.usda.gov/recarea/coconino/recarea/?recid=54892', null, 'America/Phoenix', now()),
  ('Devil''s Bridge', 'devils-bridge', 'roadside-oddities', 34.90211, -111.81324, 'Sedona', 'AZ', 'A broad natural sandstone arch forms one of Sedona''s most photographed rock features. The exposed top has steep drop-offs, so visitors should stay on established routes and use caution rather than treating the formation as a stunt location.', 'open', 'https://www.fs.usda.gov/recarea/coconino/recarea/?recid=54892', null, 'America/Phoenix', now()),
  ('Sedona Heritage Museum', 'sedona-heritage-museum', 'weird-history', 34.86939, -111.76184, 'Sedona', 'AZ', 'The museum occupies the former Jordan family farm and preserves Sedona''s ranching, orchard and early film history. It provides context for the town before red-rock tourism, vortex culture and New Age businesses transformed its identity.', 'limited', 'https://sedonamuseum.org/', null, 'America/Phoenix', now()),
  ('The Palace Restaurant & Saloon', 'the-palace-restaurant-saloon', 'weird-history', 34.54142, -112.47078, 'Prescott', 'AZ', 'A long-running Whiskey Row saloon preserves an elaborate historic bar and legends from Prescott''s frontier period. The building was reconstructed after the 1900 fire, when patrons famously carried the bar to safety across the street.', 'open', 'https://palaceprescott.com/', null, 'America/Phoenix', now()),
  ('Hotel Vendome — Room 16 Ghost Lore', 'hotel-vendome-room-16-ghost-lore', 'haunted', 34.5396, -112.46833, 'Prescott', 'AZ', 'The small historic hotel is especially known for stories involving Room 16 and a woman commonly called Abby in local ghost lore. It remains a functioning hotel, so paranormal claims should be presented as stories associated with the property rather than verified events.', 'open', 'https://vendomehotel.com/', null, 'America/Phoenix', now()),
  ('Hassayampa Inn', 'hassayampa-inn', 'haunted', 34.54236, -112.46861, 'Prescott', 'AZ', 'The 1927 hotel preserves Spanish Colonial Revival architecture and a long-running ghost story about a bride known as Faith. Guests can experience the historic building without trespassing, while OddWay should keep the haunting framed as local lore.', 'open', 'https://www.hassayampainn.com/', null, 'America/Phoenix', now()),
  ('Watson Lake & Granite Dells', 'watson-lake-granite-dells', 'roadside-oddities', 34.59074, -112.41951, 'Prescott', 'AZ', 'Rounded granite boulders crowd the shoreline of Watson Lake, creating coves and narrow passages that look almost artificial. Public trails and overlooks provide easy access to one of central Arizona''s strangest erosion landscapes.', 'open', 'https://www.prescott-az.gov/recreation-area/watson-lake-park/', null, 'America/Phoenix', now()),
  ('Lowell Observatory', 'lowell-observatory', 'weird-history', 35.20259, -111.66457, 'Flagstaff', 'AZ', 'Pluto was discovered from this hilltop observatory in 1930, and historic telescopes remain alongside modern observing facilities. Evening programs let visitors connect directly with one of Arizona''s most important astronomical sites.', 'limited', 'https://lowell.edu/', null, 'America/Phoenix', now()),
  ('Museum of Northern Arizona', 'museum-of-northern-arizona', 'museums', 35.23513, -111.66575, 'Flagstaff', 'AZ', 'Collections bring together Colorado Plateau archaeology, Indigenous art, geology and paleontology under one roof. It is especially useful for understanding the cultural and natural context behind many northern Arizona OddWay stops.', 'limited', 'https://musnaz.org/', null, 'America/Phoenix', now()),
  ('Riordan Mansion State Historic Park', 'riordan-mansion-state-historic-park', 'roadside-oddities', 35.19504, -111.65189, 'Flagstaff', 'AZ', 'Twin Arts-and-Crafts mansions connected by a common room were built for two Riordan brothers in 1904. The massive log-and-stone complex feels more like a mountain lodge puzzle than a conventional family home.', 'limited', 'https://azstateparks.com/riordan-mansion', null, 'America/Phoenix', now()),
  ('Hotel Monte Vista', 'hotel-monte-vista', 'haunted', 35.19839, -111.64834, 'Flagstaff', 'AZ', 'The 1927 downtown hotel has decades of stories involving phantom bellboys, strange voices and other alleged activity. It remains an operating lodging property, giving visitors a lawful way to experience the historic building.', 'open', 'https://hotelmontevista.com/', null, 'America/Phoenix', now()),
  ('Lava River Cave', 'lava-river-cave', 'roadside-oddities', 35.34279, -111.8359, 'Flagstaff', 'AZ', 'A mile-long lava tube left by ancient volcanic activity forms a dark, rough underground tunnel in the Coconino National Forest. There is no installed lighting, and the floor is uneven and cold, so visitors need proper equipment and should check seasonal road conditions.', 'limited', 'https://www.fs.usda.gov/recarea/coconino/recarea/?recid=55122', null, 'America/Phoenix', now()),
  ('Sunset Crater Volcano National Monument', 'sunset-crater-volcano-national-monument', 'roadside-oddities', 35.3713, -111.51045, 'Flagstaff', 'AZ', 'A cinder cone created by an eruption roughly nine centuries ago rises above black lava flows and volcanic fields northeast of Flagstaff. Trails cross stark terrain that still looks recently burned compared with the surrounding forest.', 'open', 'https://www.nps.gov/sucr/', null, 'America/Phoenix', now()),
  ('Wupatki National Monument', 'wupatki-national-monument', 'weird-history', 35.52031, -111.37122, 'Flagstaff', 'AZ', 'Large masonry pueblos rise from open volcanic desert north of Flagstaff, preserving communities that expanded after the Sunset Crater eruption. Wupatki Pueblo includes a ballcourt and unusual blowhole where underground air movement can be felt.', 'open', 'https://www.nps.gov/wupa/', null, 'America/Phoenix', now()),
  ('Walnut Canyon National Monument', 'walnut-canyon-national-monument', 'weird-history', 35.16878, -111.50294, 'Flagstaff', 'AZ', 'Cliff dwellings are tucked into narrow limestone ledges below the rim of Walnut Canyon. A steep developed trail lets visitors pass directly beside protected rooms while interpreting how people lived in the canyon centuries ago.', 'open', 'https://www.nps.gov/waca/', null, 'America/Phoenix', now()),
  ('Twin Arrows Trading Post Ruins', 'twin-arrows-trading-post-ruins', 'roadside-oddities', 35.16186, -111.26918, 'Twin Arrows', 'AZ', 'Two giant arrows mark the remains of a once-famous Route 66 trading post. The commercial buildings are ruins and access can be restricted, so OddWay should use a safe public viewing point and never encourage entry into unstable structures.', 'roadside', 'https://www.nps.gov/subjects/travelroute66/index.htm', null, 'America/Phoenix', now()),
  ('Two Guns Ghost Town & Apache Death Cave Lore', 'two-guns-ghost-town-apache-death-cave-lore', 'weird-history', 35.11611, -111.09358, 'Two Guns', 'AZ', 'Ruins of a Route 66 tourist complex and trading stop survive near Canyon Diablo, alongside a heavily mythologized story commonly called the Apache Death Cave. Much of the property is private or unsafe, so this is a lawful roadside/view-only history stop and the cave story should be treated as legend rather than unquestioned fact.', 'roadside', 'https://www.nps.gov/subjects/travelroute66/index.htm', null, 'America/Phoenix', now()),
  ('Meteor Crater', 'meteor-crater', 'weird-history', 35.02753, -111.02266, 'Winslow', 'AZ', 'A meteorite impact roughly 50,000 years ago blasted a crater nearly a mile wide into the high desert. Developed overlooks and exhibits make one of the world''s best-preserved impact craters easy to see without entering the protected depression.', 'limited', 'https://meteorcrater.com/', null, 'America/Phoenix', now()),
  ('La Posada Hotel', 'la-posada-hotel', 'roadside-oddities', 35.02172, -110.69516, 'Winslow', 'AZ', 'Mary Colter designed this elaborate railroad hotel as a romanticized Southwestern estate for Fred Harvey and the Santa Fe Railway. Restored rooms, art and active tracks preserve the strange overlap between luxury tourism and rail infrastructure.', 'open', 'https://laposada.org/', null, 'America/Phoenix', now()),
  ('Standin'' on the Corner Park', 'standin-on-the-corner-park', 'roadside-oddities', 35.02417, -110.69743, 'Winslow', 'AZ', 'A downtown corner has been transformed into a public monument to the lyric that made Winslow famous, complete with mural, flatbed Ford and bronze figure. It is a rare case where a single line of a song permanently reshaped a real town intersection.', 'open', 'https://www.standinonthecorner.org/', null, 'America/Phoenix', now()),
  ('Homolovi State Park', 'homolovi-state-park', 'weird-history', 35.04096, -110.64621, 'Winslow', 'AZ', 'Protected pueblo ruins and artifact scatters preserve ancestral Hopi settlements along the Little Colorado River. The park works closely with Hopi perspectives, so archaeological material should be treated as living cultural heritage rather than abandoned curiosities.', 'open', 'https://azstateparks.com/homolovi', null, 'America/Phoenix', now()),
  ('Jack Rabbit Trading Post', 'jack-rabbit-trading-post', 'roadside-oddities', 34.95451, -110.44877, 'Joseph City', 'AZ', 'A giant jackrabbit and the famous ''HERE IT IS'' sign mark one of Route 66''s classic trading-post survivors. Decades of billboards turned the rabbit into a roadside destination long before travelers reached the store itself.', 'open', 'https://jackrabbittradingpost.com/', null, 'America/Phoenix', now()),
  ('Wigwam Motel', 'wigwam-motel', 'roadside-oddities', 34.9022, -110.15887, 'Holbrook', 'AZ', 'Guests sleep in concrete teepee-shaped motel rooms arranged around vintage cars at this 1950 Route 66 landmark. The architecture reflects mid-century roadside fantasy rather than authentic Indigenous housing and should be described accordingly.', 'open', 'https://sleepinawigwam.com/', null, 'America/Phoenix', now()),
  ('Bucket of Blood Street', 'bucket-of-blood-street', 'weird-history', 34.90292, -110.16061, 'Holbrook', 'AZ', 'A short Holbrook street carries the theatrical name ''Bucket of Blood,'' tied by local tradition to the rough reputation of the railroad town''s saloon era. The surviving street sign gives the legend a concrete, routable point.', 'open', 'https://www.holbrookaz.gov/', null, 'America/Phoenix', now()),
  ('Rainbow Rock Shop Dinosaurs', 'rainbow-rock-shop-dinosaurs', 'roadside-oddities', 34.91876, -110.11767, 'Holbrook', 'AZ', 'Large homemade dinosaur figures surround a long-running petrified-wood and rock shop on Route 66. The concrete creatures turn a geology store into a classic roadside photo stop.', 'open', 'https://www.facebook.com/RainbowRockShop/', null, 'America/Phoenix', now()),
  ('Jim Gray''s Petrified Wood Co.', 'jim-grays-petrified-wood-co', 'roadside-oddities', 34.91302, -110.14127, 'Holbrook', 'AZ', 'Enormous petrified logs, stone displays and dinosaur figures cover the grounds of this long-running Holbrook rock business. The sheer scale of fossilized wood outside makes it function like a free roadside geology museum before visitors enter the shop.', 'open', 'https://jimgrayspetrifiedwood.com/', null, 'America/Phoenix', now()),
  ('Painted Desert Inn', 'painted-desert-inn', 'roadside-oddities', 35.08302, -109.78802, 'Petrified Forest National Park', 'AZ', 'This Pueblo Revival landmark on the Painted Desert rim evolved from a petrified-wood tourist building into a Fred Harvey-era inn redesigned by Mary Colter. It now serves as a museum and viewpoint rather than overnight lodging.', 'open', 'https://www.nps.gov/pefo/learn/historyculture/painted-desert-inn.htm', null, 'America/Phoenix', now()),
  ('Route 66 Studebaker — Petrified Forest', 'route-66-studebaker-petrified-forest', 'roadside-oddities', 35.04341, -109.79813, 'Petrified Forest National Park', 'AZ', 'A rusting 1932 Studebaker marks where historic Route 66 once crossed what is now Petrified Forest National Park. Utility poles fading into the desert make the abandoned road alignment visible even after the pavement disappeared.', 'open', 'https://www.nps.gov/pefo/learn/historyculture/route-66.htm', null, 'America/Phoenix', now()),
  ('Puerco Pueblo', 'puerco-pueblo', 'weird-history', 34.99866, -109.7853, 'Petrified Forest National Park', 'AZ', 'Stone foundations and nearby petroglyphs preserve a large ancestral pueblo once occupied along the Puerco River. A developed trail lets visitors see the protected site without entering the archaeological remains.', 'open', 'https://www.nps.gov/pefo/learn/historyculture/puerco-pueblo.htm', null, 'America/Phoenix', now()),
  ('Newspaper Rock', 'newspaper-rock', 'weird-history', 34.96836, -109.80234, 'Petrified Forest National Park', 'AZ', 'Hundreds of petroglyphs crowd dark boulders below an overlook, creating one of the park''s densest rock-art concentrations. Visitors view the panels from above to protect the archaeological site.', 'open', 'https://www.nps.gov/pefo/learn/historyculture/newspaper-rock.htm', null, 'America/Phoenix', now()),
  ('Blue Mesa', 'blue-mesa', 'roadside-oddities', 34.9409, -109.75605, 'Petrified Forest National Park', 'AZ', 'Bands of blue, purple and gray bentonite form steep badlands around pieces of petrified wood. A loop road and trail descend into terrain that looks more extraterrestrial than typical Arizona desert.', 'open', 'https://www.nps.gov/pefo/planyourvisit/blue-mesa.htm', null, 'America/Phoenix', now()),
  ('Agate Bridge', 'agate-bridge', 'roadside-oddities', 34.87531, -109.78956, 'Petrified Forest National Park', 'AZ', 'A long petrified log spans a natural wash like a stone bridge and is now supported by an old concrete beam installed to keep it from breaking. The awkward human reinforcement has become part of the oddity.', 'open', 'https://www.nps.gov/pefo/learn/nature/petrified-wood.htm', null, 'America/Phoenix', now()),
  ('Giant Logs Trail', 'giant-logs-trail', 'roadside-oddities', 34.81543, -109.86569, 'Petrified Forest National Park', 'AZ', 'Massive sections of petrified trees lie across the ground near the park''s Rainbow Forest Museum, including some of the largest visible logs in the park. A short developed trail makes the fossil forest easy to inspect at close range without collecting anything.', 'open', 'https://www.nps.gov/pefo/planyourvisit/giant-logs.htm', null, 'America/Phoenix', now()),
  ('Casa Malpais Archaeological Park', 'casa-malpais-archaeological-park', 'weird-history', 34.13419, -109.28507, 'Springerville', 'AZ', 'A hilltop archaeological site preserves pueblo rooms, a Great Kiva, solar-calendar features and an unusual basalt staircase. Access is controlled through the Springerville Heritage Center and guided-tour program.', 'limited', 'https://www.springervilleaz.gov/casa-malpais', null, 'America/Phoenix', now()),
  ('White Mountain Dinosaur Exploration Center', 'white-mountain-dinosaur-exploration-center', 'museums', 34.13326, -109.28564, 'Springerville', 'AZ', 'This small research-focused museum shares dinosaur discoveries from the Zuni Basin and surrounding formations, including material connected with newly described species. It is tied directly to active regional paleontology rather than a generic dinosaur display.', 'limited', 'https://zdig.org/', null, 'America/Phoenix', now()),
  ('Fort Apache Historic Park', 'fort-apache-historic-park', 'weird-history', 33.79022, -109.98786, 'Fort Apache', 'AZ', 'Historic U.S. Army buildings and the White Mountain Apache Cultural Center occupy a landscape central to Apache and military history. The site is on tribal land and should be visited under current White Mountain Apache rules and hours.', 'limited', 'https://www.fortapachearizona.org/', null, 'America/Phoenix', now()),
  ('Kinishba Ruins National Historic Landmark', 'kinishba-ruins-national-historic-landmark', 'weird-history', 33.82372, -110.05428, 'Fort Apache', 'AZ', 'Hundreds of masonry rooms survive at this large ancestral pueblo on White Mountain Apache tribal land. Visitors must follow current check-in and access procedures through Fort Apache rather than simply driving into the archaeological site.', 'limited', 'https://www.fortapachearizona.org/kinishba', null, 'America/Phoenix', now()),
  ('Clifton Cliff Jail', 'clifton-cliff-jail', 'weird-history', 33.05087, -109.29669, 'Clifton', 'AZ', 'Clifton''s old jail was blasted directly into a rock cliff, creating barred cells inside the stone itself. Interior access is not reliably public, so OddWay should treat it as an exterior historic oddity unless an authorized opening is posted.', 'roadside', 'https://www.visitgreenleecounty.com/', null, 'America/Phoenix', now()),
  ('Morenci Mine Overlook', 'morenci-mine-overlook', 'roadside-oddities', 33.05764, -109.36697, 'Morenci', 'AZ', 'A roadside overlook reveals one of the largest open-pit copper mines in North America, where benches and haul roads transform entire mountainsides. Visitors should remain at designated viewpoints and never enter operating mine property.', 'roadside', 'https://www.visitgreenleecounty.com/', null, 'America/Phoenix', now()),
  ('Delgadillo''s Snow Cap', 'delgadillos-snow-cap', 'roadside-oddities', 35.32593, -112.87305, 'Seligman', 'AZ', 'Juan Delgadillo built this eccentric Route 66 drive-in from scrap lumber in 1953 and surrounded it with visual jokes, signs and deliberately corny gags. The family-run stop became one of Seligman''s defining pieces of roadside culture.', 'open', 'https://www.snowcap66.com/', null, 'America/Phoenix', now()),
  ('Angel & Vilma Delgadillo''s Original Route 66 Gift Shop', 'angel-vilma-delgadillos-original-route-66-gift-shop', 'roadside-oddities', 35.32631, -112.87431, 'Seligman', 'AZ', 'Angel Delgadillo''s former barbershop became headquarters for the effort that helped establish Historic Route 66 in Arizona. The operating gift shop preserves memorabilia and the story of the people who helped revive the road after interstate bypasses nearly erased it.', 'open', 'https://www.route66giftshop.com/', null, 'America/Phoenix', now()),
  ('Grand Canyon Caverns', 'grand-canyon-caverns', 'roadside-oddities', 35.52833, -113.23132, 'Peach Springs', 'AZ', 'An elevator descends roughly 200 feet into a large dry cave system beneath Route 66. Tours, old civil-defense supplies and the underground suite make the caverns an unusually deep roadside attraction.', 'limited', 'https://gccaverns.com/', null, 'America/Phoenix', now()),
  ('Hackberry General Store', 'hackberry-general-store', 'roadside-oddities', 35.37492, -113.72286, 'Hackberry', 'AZ', 'Vintage gas pumps, signs, cars and roadside debris crowd this former Route 66 service stop. The store and its yard preserve the dense visual language of the highway better than a polished recreation would.', 'open', 'https://www.hackberrygeneralstore.com/', null, 'America/Phoenix', now()),
  ('Giganticus Headicus', 'giganticus-headicus', 'roadside-oddities', 35.41888, -113.8082, 'Antares', 'AZ', 'A towering green tiki-style head rises beside Route 66 at Antares Point, surrounded by additional sculpture and remnants of an old roadside business. It is modern outsider art deliberately built to become a highway landmark.', 'open', 'https://www.giganticusheadicus.com/', null, 'America/Phoenix', now()),
  ('Arizona Route 66 Museum', 'arizona-route-66-museum', 'roadside-oddities', 35.18911, -114.05898, 'Kingman', 'AZ', 'Inside Kingman''s historic Powerhouse, exhibits trace travel across northern Arizona from wagon roads to Route 66 tourism. Vehicles, signs and roadside displays make it a useful anchor for understanding the oddities along the road outside.', 'limited', 'https://www.kingmanvisitorcenter.com/arizona-route-66-museum', null, 'America/Phoenix', now()),
  ('Historic Mohave County Jail', 'historic-mohave-county-jail', 'weird-history', 35.1899, -114.05586, 'Kingman', 'AZ', 'The old county jail stands near Kingman''s historic courthouse complex as a reminder of territorial and early-state law enforcement. Interior access is not consistently offered, so this should default to an exterior history stop unless local authorities announce tours.', 'roadside', 'https://www.explorekingman.com/', null, 'America/Phoenix', now()),
  ('El Trovatore Motel', 'el-trovatore-motel', 'roadside-oddities', 35.21455, -114.02522, 'Kingman', 'AZ', 'A tall neon sign and huge murals turn this 1930s Route 66 motel into a roadside landmark long before travelers reach the rooms. It remains an operating motel rather than a preserved museum piece.', 'open', 'https://www.eltrovatore.com/', null, 'America/Phoenix', now()),
  ('Route 66 Drive-Thru Shield', 'route-66-drive-thru-shield', 'roadside-oddities', 35.18906, -114.05785, 'Kingman', 'AZ', 'An oversized Route 66 shield at the Kingman Visitor Center is built with an opening large enough for a vehicle to pass through. The deliberately photogenic structure turns the highway emblem into a piece of interactive roadside art.', 'open', 'https://www.explorekingman.com/', null, 'America/Phoenix', now()),
  ('Cool Springs Station', 'cool-springs-station', 'roadside-oddities', 35.02744, -114.30903, 'Golden Valley', 'AZ', 'Rebuilt on the footprint of a historic Route 66 stop, Cool Springs uses stone architecture, fuel pumps and desert isolation to evoke the old mountain road toward Oatman. The site operates as a small museum and gift stop rather than an abandoned gas station.', 'open', 'https://www.route66coolspringsaz.com/', null, 'America/Phoenix', now()),
  ('Oatman Hotel', 'oatman-hotel', 'haunted', 35.02659, -114.38395, 'Oatman', 'AZ', 'The 1902 hotel is one of Oatman''s most recognizable buildings and is tied to mining-town history, Clark Gable honeymoon lore and ghost stories. The ground-floor restaurant and bar remain public even though it no longer functions as a conventional hotel.', 'open', 'https://www.oatmanhotel.com/', null, 'America/Phoenix', now()),
  ('Raptor Ranch & Historic Bedrock City', 'raptor-ranch-historic-bedrock-city', 'roadside-oddities', 35.65412, -112.14137, 'Valle', 'AZ', 'The old Flintstones-themed Bedrock City survives inside Raptor Ranch, where concrete cartoon buildings now share the property with a birds-of-prey attraction and campground. The operator explicitly states that Bedrock remains open, preserving a rare 1970s roadside theme park.', 'limited', 'https://raptor-ranch.com/attractions/bedrock-city/', null, 'America/Phoenix', now()),
  ('Grand Canyon Railway Depot — South Rim', 'grand-canyon-railway-depot-south-rim', 'weird-history', 36.05654, -112.13649, 'Grand Canyon Village', 'AZ', 'Historic trains still deliver passengers to this log depot only steps from the South Rim. It is one of the few U.S. national-park railroad stations still serving regular passenger excursions.', 'open', 'https://www.nps.gov/grca/learn/historyculture/grand-canyon-railway.htm', null, 'America/Phoenix', now()),
  ('Desert View Watchtower', 'desert-view-watchtower', 'roadside-oddities', 36.04401, -111.82621, 'Grand Canyon Village', 'AZ', 'Mary Colter designed this 70-foot stone tower to resemble ancestral Southwestern architecture while functioning as a dramatic Grand Canyon overlook. Interior murals and the layered masonry make it one of the park''s strangest constructed landmarks.', 'open', 'https://www.nps.gov/places/000/desert-view-watchtower.htm', null, 'America/Phoenix', now()),
  ('Kolb Studio', 'kolb-studio', 'roadside-oddities', 36.05796, -112.1426, 'Grand Canyon Village', 'AZ', 'The Kolb brothers built their photography studio directly on the canyon rim at the head of Bright Angel Trail, where they documented early tourism and river expeditions. The precarious-looking building now contains exhibits and a shop.', 'open', 'https://www.nps.gov/places/000/kolb-studio.htm', null, 'America/Phoenix', now()),
  ('Navajo Bridge', 'navajo-bridge', 'roadside-oddities', 36.81784, -111.6317, 'Marble Canyon', 'AZ', 'The original 1929 steel arch bridge spans Marble Canyon hundreds of feet above the Colorado River and now serves pedestrians beside the newer highway bridge. California condors are sometimes seen around the cliffs and bridge structure.', 'open', 'https://www.nps.gov/glca/learn/historyculture/navajo-bridge.htm', null, 'America/Phoenix', now()),
  ('Lees Ferry', 'lees-ferry', 'weird-history', 36.86626, -111.58652, 'Marble Canyon', 'AZ', 'A historic river crossing, ferry site and modern launch point occupy one of the few places where travelers can easily reach the Colorado River between high canyon walls. Remains of settlement and ferry history sit within Glen Canyon National Recreation Area.', 'open', 'https://www.nps.gov/glca/planyourvisit/lees-ferry.htm', null, 'America/Phoenix', now()),
  ('Lonely Dell Ranch', 'lonely-dell-ranch', 'weird-history', 36.86451, -111.5976, 'Marble Canyon', 'AZ', 'Orchards, ranch buildings and a small cemetery preserve the isolated homestead associated with the Lees Ferry crossing. A short gravel-road detour reaches the historic district from the ferry area.', 'open', 'https://www.nps.gov/glca/learn/historyculture/lonely-dell-ranch.htm', null, 'America/Phoenix', now()),
  ('Carl Hayden Visitor Center & Glen Canyon Dam', 'carl-hayden-visitor-center-glen-canyon-dam', 'roadside-oddities', 36.93575, -111.48559, 'Page', 'AZ', 'A mid-century visitor center overlooks the enormous concrete Glen Canyon Dam and its bridge across the Colorado River. Exhibits and ranger programs explain the engineering project and the environmental transformation that created Lake Powell.', 'open', 'https://www.nps.gov/glca/planyourvisit/carl-hayden-visitor-center.htm', null, 'America/Denver', now()),
  ('Horseshoe Bend', 'horseshoe-bend', 'roadside-oddities', 36.87917, -111.51039, 'Page', 'AZ', 'The Colorado River wraps almost completely around a sandstone butte below a high public overlook. A developed trail and railing at the main viewpoint make this dramatic entrenched meander a straightforward road-trip stop.', 'open', 'https://www.nps.gov/glca/planyourvisit/horseshoe-bend.htm', null, 'America/Denver', now()),
  ('Upper Antelope Canyon', 'upper-antelope-canyon', 'roadside-oddities', 36.86191, -111.37433, 'Page', 'AZ', 'Narrow sandstone walls twist into wave-like passages shaped by flash floods and wind. The canyon is on Navajo Nation land and may only be visited through authorized Navajo-guided tours.', 'limited', 'https://navajonationparks.org/guided-tour-operators/antelope-canyon-tour-operators/', null, 'America/Denver', now()),
  ('Navajo National Monument', 'navajo-national-monument', 'weird-history', 36.67815, -110.54104, 'Shonto', 'AZ', 'Cliff dwellings including Betatakin and Keet Seel are protected in remote canyons on the Navajo Nation. Self-guided rim trails are readily accessible, while backcountry dwelling access is tightly controlled and may require ranger-led programs.', 'open', 'https://www.nps.gov/nava/', null, 'America/Denver', now()),
  ('Hubbell Trading Post National Historic Site', 'hubbell-trading-post-national-historic-site', 'weird-history', 35.70727, -109.55995, 'Ganado', 'AZ', 'A working trading post, homestead and ranch complex preserve the long history of commerce between Navajo artists, local residents and outside traders. The National Park Service maintains the site while trading activity continues.', 'open', 'https://www.nps.gov/hutr/', null, 'America/Denver', now()),
  ('Spider Rock Overlook', 'spider-rock-overlook', 'roadside-oddities', 36.10559, -109.35541, 'Chinle', 'AZ', 'A developed overlook faces the twin sandstone spires of Spider Rock rising from Canyon de Chelly. The formation is culturally significant within Diné tradition, so visitors should use the public rim viewpoint and treat associated stories respectfully.', 'open', 'https://www.nps.gov/cach/planyourvisit/south-rim-drive.htm', null, 'America/Denver', now()),
  ('Four Corners Monument', 'four-corners-monument', 'roadside-oddities', 36.99898, -109.04518, 'Teec Nos Pos', 'AZ', 'A survey monument marks the only point in the United States where four states meet. The site is operated by Navajo Nation Parks and Recreation, and visitors should follow tribal hours, fees and rules.', 'limited', 'https://navajonationparks.org/four-corners-monument/', null, 'America/Denver', now()),
  ('Monument Valley Navajo Tribal Park', 'monument-valley-navajo-tribal-park', 'roadside-oddities', 36.98241, -110.11179, 'Oljato-Monument Valley', 'AZ', 'Monument Valley''s isolated sandstone buttes form one of the most recognizable landscapes in the American Southwest. The park is Navajo Nation land; access beyond designated public areas is controlled and some routes require guides or permits.', 'limited', 'https://navajonationparks.org/tribal-parks/monument-valley/', null, 'America/Denver', now()),
  ('Window Rock Navajo Tribal Park & Veterans Memorial', 'window-rock-navajo-tribal-park-veterans-memorial', 'roadside-oddities', 35.67735, -109.05266, 'Window Rock', 'AZ', 'A large natural sandstone arch gives the Navajo Nation capital its English name, and the adjacent park contains a memorial honoring Navajo veterans. The site combines a striking geologic formation with living governmental and cultural significance.', 'open', 'https://www.discovernavajo.com/', null, 'America/Denver', now()),
  ('Navajo Nation Museum', 'navajo-nation-museum', 'weird-history', 35.66576, -109.0646, 'Window Rock', 'AZ', 'The Navajo Nation''s own museum presents Diné history, culture, art and contemporary experience from a tribal perspective. It is a key corrective to visiting archaeological or cultural sites only through outside interpretation.', 'limited', 'https://www.navajo-nsn.gov/History', null, 'America/Denver', now()),
  ('Navajo Code Talkers Memorial', 'navajo-code-talkers-memorial', 'weird-history', 35.67701, -109.0533, 'Window Rock', 'AZ', 'A memorial near the Navajo Nation government complex honors the Diné Marines whose language-based code was used during World War II. The site should be treated as a solemn military and tribal-history stop.', 'open', 'https://www.discovernavajo.com/', null, 'America/Denver', now()),
  ('Navajo Nation Zoo', 'navajo-nation-zoo', 'roadside-oddities', 35.66229, -109.05866, 'Window Rock', 'AZ', 'The Navajo Nation operates this small zoo and botanical park with native Southwest animals and culturally informed interpretation. It is the only tribally owned zoo in the United States and connects wildlife displays with Diné perspectives.', 'limited', 'https://www.navajozoo.org/', null, 'America/Denver', now()),
  ('Tuba City Dinosaur Tracks', 'tuba-city-dinosaur-tracks', 'roadside-oddities', 36.01673, -111.03332, 'Tuba City', 'AZ', 'Dinosaur footprints are visible in exposed rock near U.S. 160 on Navajo Nation land. Local guides commonly interpret the site; visitors should follow current landowner/tribal expectations and avoid damaging or removing material.', 'limited', 'https://www.discovernavajo.com/', null, 'America/Denver', now()),
  ('Burger King Navajo Code Talkers Exhibit', 'burger-king-navajo-code-talkers-exhibit', 'museums', 36.71409, -110.25912, 'Kayenta', 'AZ', 'A fast-food restaurant contains a surprisingly substantial display of Navajo Code Talker photographs, uniforms and military memorabilia assembled by a local veteran family. The contrast between the setting and the serious collection makes it one of Arizona''s strangest small-history stops.', 'open', 'https://www.discovernavajo.com/', null, 'America/Denver', now()),
  ('White House Overlook — Canyon de Chelly', 'white-house-overlook-canyon-de-chelly', 'weird-history', 36.13614, -109.4709, 'Chinle', 'AZ', 'The rim overlook looks down toward ancestral cliff dwellings set into Canyon de Chelly''s sandstone wall. Canyon lands remain Navajo Nation property, so visitors should stay on authorized overlooks unless participating in permitted access below the rim.', 'open', 'https://www.nps.gov/cach/planyourvisit/north-and-south-rim-drives.htm', null, 'America/Denver', now()),
  ('London Bridge', 'london-bridge', 'roadside-oddities', 34.47176, -114.34725, 'Lake Havasu City', 'AZ', 'The 1830s London Bridge was dismantled in England, shipped to Arizona and reconstructed over a man-made channel in Lake Havasu City. The real nineteenth-century masonry wrapped around a modern structure creates one of America''s most elaborate imported roadside landmarks.', 'open', 'https://www.golakehavasu.com/london-bridge/', null, 'America/Phoenix', now()),
  ('Lake Havasu Lighthouse Trail', 'lake-havasu-lighthouse-trail', 'roadside-oddities', 34.46584, -114.35634, 'Lake Havasu City', 'AZ', 'Dozens of functioning lighthouse replicas line the lake and island shoreline, each modeled after a real American lighthouse. The desert setting makes the miniature maritime landscape deliberately surreal.', 'open', 'https://www.golakehavasu.com/lighthouses/', null, 'America/Phoenix', now()),
  ('Swansea Historic Ghost Town', 'swansea-historic-ghost-town', 'weird-history', 34.17203, -113.84707, 'Swansea', 'AZ', 'Ruins, mine structures and building foundations mark a remote copper town abandoned after repeated economic failures. The Bureau of Land Management manages the site, but desert roads can be rough and visitors should prepare for remote conditions.', 'limited', 'https://www.blm.gov/visit/swansea-townsite', null, 'America/Phoenix', now()),
  ('Hi Jolly Monument', 'hi-jolly-monument', 'weird-history', 33.66547, -114.22997, 'Quartzsite', 'AZ', 'A stone pyramid topped by a metal camel marks the grave of Hadji Ali, known as Hi Jolly, who worked with the U.S. Army''s experimental Camel Corps. The monument turns one of the strangest episodes in American military transportation into a visible desert landmark.', 'open', 'https://www.quartzsitemuseum.com/hi-jolly', null, 'America/Phoenix', now()),
  ('Tyson''s Well Stage Station Museum', 'tysons-well-stage-station-museum', 'weird-history', 33.66645, -114.21831, 'Quartzsite', 'AZ', 'An adobe stage station dating to the nineteenth century survives as Quartzsite''s local museum, surrounded by mining and pioneer artifacts. The building predates the enormous seasonal RV culture that now defines the town.', 'limited', 'https://www.quartzsitemuseum.com/', null, 'America/Phoenix', now()),
  ('Bouse Fisherman Intaglio', 'bouse-fisherman-intaglio', 'weird-history', 33.94554, -113.99957, 'Bouse', 'AZ', 'A huge human-shaped geoglyph is scraped into desert pavement outside Bouse, one of several mysterious Colorado River-area intaglios. Visitors should use established access and never walk on or disturb the fragile ground figure.', 'limited', 'https://www.blm.gov/visit/bouse-fisherman-intaglio', null, 'America/Phoenix', now()),
  ('Camp Bouse', 'camp-bouse', 'weird-history', 33.88832, -113.93249, 'Bouse', 'AZ', 'Remote desert remains mark a secret World War II training camp used for experimental armored-vehicle night-fighting technology. Concrete pads, roads and scattered artifacts survive, but this is a remote desert-history site requiring route and road-condition awareness.', 'limited', 'https://www.blm.gov/visit/camp-bouse', null, 'America/Phoenix', now()),
  ('Castle Dome Mine Museum', 'castle-dome-mine-museum', 'weird-history', 33.0477, -114.1785, 'Yuma', 'AZ', 'Dozens of reconstructed and relocated buildings create an immersive mining-town museum in the Castle Dome district. Artifacts, mine history and desert isolation make the site feel much larger than a conventional indoor museum.', 'limited', 'https://www.castledomemuseum.org/', null, 'America/Phoenix', now()),
  ('Yuma Territorial Prison State Historic Park', 'yuma-territorial-prison-state-historic-park', 'weird-history', 32.72755, -114.61493, 'Yuma', 'AZ', 'Cells, guard structures and exhibits survive from the territorial prison that operated here from 1876 to 1909. The hilltop site overlooks the Colorado River and preserves one of Arizona''s strongest lawful prison-history destinations.', 'limited', 'https://azstateparks.com/yuma-territorial', null, 'America/Phoenix', now()),
  ('Colorado River State Historic Park', 'colorado-river-state-historic-park', 'weird-history', 32.72573, -114.61799, 'Yuma', 'AZ', 'Former Army quartermaster-depot buildings preserve the logistics hub that supplied military posts throughout the Southwest. Warehouses and river history show how much nineteenth-century Arizona depended on the Colorado as a transportation route.', 'limited', 'https://azstateparks.com/colorado-river', null, 'America/Phoenix', now()),
  ('Sanguinetti House Museum & Gardens', 'sanguinetti-house-museum-gardens', 'weird-history', 32.72482, -114.62022, 'Yuma', 'AZ', 'A merchant''s adobe home preserves Yuma''s late nineteenth- and early twentieth-century domestic and commercial history. Period rooms and shaded gardens contrast sharply with the prison and military sites only blocks away.', 'limited', 'https://arizonahistoricalsociety.org/museum/sanguinetti-house-museum-gardens/', null, 'America/Phoenix', now()),
  ('Pivot Point Interpretive Plaza', 'pivot-point-interpretive-plaza', 'weird-history', 32.72457, -114.61518, 'Yuma', 'AZ', 'A full-size steam locomotive display and laser/light interpretation mark the point where the first railroad crossed the Colorado River at Yuma. The plaza turns invisible transportation history into a large mechanical landmark on the riverfront.', 'open', 'https://www.visityuma.com/things-to-do/history-and-museums/pivot-point/', null, 'America/Phoenix', now()),
  ('Ocean-to-Ocean Bridge', 'ocean-to-ocean-bridge', 'roadside-oddities', 32.73148, -114.61671, 'Yuma', 'AZ', 'This 1915 bridge carried early transcontinental automobile traffic across the Colorado River and helped make an ''ocean-to-ocean'' highway practical. Its surviving steel structure is now a historic river crossing rather than the main traffic route.', 'open', 'https://www.visityuma.com/things-to-do/history-and-museums/ocean-to-ocean-bridge/', null, 'America/Phoenix', now()),
  ('Painted Rock Petroglyph Site', 'painted-rock-petroglyph-site', 'weird-history', 33.02418, -113.04584, 'Gila Bend', 'AZ', 'Hundreds of petroglyphs cover dark volcanic boulders in a protected desert site north of Gila Bend. Visitors should stay on designated paths and never touch, chalk or climb on the rock-art panels.', 'limited', 'https://www.blm.gov/visit/painted-rock-petroglyph-site', null, 'America/Phoenix', now()),
  ('Space Age Lodge', 'space-age-lodge', 'roadside-oddities', 32.94731, -112.71688, 'Gila Bend', 'AZ', 'A giant flying-saucer sign and space-themed architecture have made this motel a Gila Bend landmark since the Space Age. The property remains an operating motel, preserving mid-century futurism in the middle of the desert.', 'open', 'https://www.bestwestern.com/en_US/book/hotels-in-gila-bend/best-western-space-age-lodge/propertyCode.03053.html', null, 'America/Phoenix', now()),
  ('Ajo Mine Overlook', 'ajo-mine-overlook', 'roadside-oddities', 32.37402, -112.88663, 'Ajo', 'AZ', 'A public overlook faces the enormous New Cornelia open-pit copper mine immediately beside Ajo. Layered benches and vivid rock colors reveal how completely mining reshaped the desert landscape.', 'roadside', 'https://www.visitarizona.com/places/cities/ajo/', null, 'America/Phoenix', now()),
  ('Ajo Historical Society Museum', 'ajo-historical-society-museum', 'museums', 32.37112, -112.85916, 'Ajo', 'AZ', 'Housed in the historic St. Catherine''s Indian Mission building, the museum preserves mining, community and desert history from Ajo. Its collections give context to the huge open pit visible just outside town.', 'limited', 'https://www.ajomuseumandhistoricalsociety.com/', null, 'America/Phoenix', now()),
  ('Desert Bar / Nellie E Saloon', 'desert-bar-nellie-e-saloon', 'roadside-oddities', 34.20281, -114.15135, 'Parker', 'AZ', 'A remote solar-powered bar built in the desert outside Parker is reached by an unpaved road and surrounded by recycled structures, metal art and a church-like facade. It operates seasonally and road conditions matter, making it a check-ahead destination rather than an ordinary restaurant stop.', 'limited', 'https://thedesertbar.com/', null, 'America/Phoenix', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  timezone      = excluded.timezone,
  verified_at   = excluded.verified_at;

select count(*) as arizona from public.stops where state = 'AZ';
